add({name:'hospital_download_file',description:'Read an authorized hospital attachment in bounded base64 chunks. Center users can read only their own receipts and currently published manual attachments.',inputSchema:obj({id,offset:integer(0,10485760),length:integer(1,65536)},['id']),write:false,run:async(a,o)=>{const r=await hospitalFiles.GET(req(o,'/api/hospital/files','GET',undefined,{id:a.id}));if(!r.ok)return result(r);const bytes=new Uint8Array(await r.arrayBuffer()),offset=a.offset||0,end=Math.min(bytes.length,offset+(a.length||65536));if(offset>bytes.length)throw new AccessError('Invalid offset',400);return {base64:btoa(String.fromCharCode(...bytes.slice(offset,end))),offset,nextOffset:end<bytes.length?end:null,totalBytes:bytes.length};}});

